158	/**
159	 * Reconstruct OpenAI chat-format message history from response_items preceding
160	 * the current index. Used to populate LLM span inputs so the MLflow Chat view
161	 * shows the full conversation context that led up to each assistant call.
162	 *
163	 * Maps Codex's Responses-API-style records to standard chat messages:
164	 * - `message` (user/assistant/system) → `{role, content}`
165	 * - `function_call` → assistant message with `tool_calls: [{id, type, function}]`
166	 * - `function_call_output` → `{role: 'tool', tool_call_id, content}`
167	 */
168	export function reconstructMessages(
169	  responseItems: RolloutLine[],
170	  uptoIndex: number,
171	): ChatMessage[] {
172	  const messages: ChatMessage[] = [];
173	  for (let i = 0; i < uptoIndex; i++) {
174	    const payload = responseItems[i].payload as ResponseItemPayload;
175	
176	    if (payload.type === 'message') {
177	      const text = extractTextFromContent(payload.content);
178	      if (!text.trim()) {
179	        continue;
180	      }
181	      if (payload.role === 'user' || payload.role === 'assistant') {
182	        messages.push({ role: payload.role, content: text });
183	      } else if (payload.role === 'developer') {
184	        // Codex uses "developer" for system-style instructions; render as system
185	        messages.push({ role: 'system', content: text });
186	      }
187	    } else if (payload.type === 'function_call') {
188	      messages.push({
189	        role: 'assistant',
190	        content: null,
191	        tool_calls: [
192	          {
193	            id: payload.call_id ?? '',
194	            type: 'function',
195	            function: {
196	              name: payload.name ?? 'unknown',
197	              arguments: payload.arguments ?? '{}',
198	            },
199	          },
200	        ],
201	      });
202	    } else if (payload.type === 'function_call_output') {
203	      messages.push({
204	        role: 'tool',
205	        tool_call_id: payload.call_id ?? '',
206	        content: payload.output ?? '',
207	      });
208	    }
209	  }
210	  return messages;
211	}
