5	export function readStdin<T>(): Promise<T> {
6	  return new Promise((resolve, reject) => {
7	    let data = '';
8	    process.stdin.setEncoding('utf-8');
9	    process.stdin.on('data', (chunk: string) => {
10	      data += chunk;
11	    });
12	    process.stdin.on('end', () => {
13	      try {
14	        resolve(JSON.parse(data) as T);
15	      } catch (err) {
16	        reject(new Error(`Failed to parse stdin JSON: ${String(err)}`));
17	      }
18	    });
19	    process.stdin.on('error', reject);
20	  });
21	}
