[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/claude-code/src/types.ts", "content": "/**
 * Types for Claude Code transcript parsing.
 *
 * Claude Code writes session transcripts as JSONL files, one entry per line.
 * Entries use an Anthropic-style `message: {role, content}` envelope where
 * `content` is either a plain string or an array of content blocks:
 *   - `{type: 'text', text}` — model/user text
 *   - `{type: 'tool_use', id, name, input}` — model requesting a tool call
 *   - `{type: 'tool_result', tool_use_id, content, is_error}` — tool output
 *     returned to the model (carried inside a `user` entry)
 *
 * Sub-agents (spawned via the `Task` tool) appear in one of two ways:
 *   - Inline `progress` entries whose `parentToolUseID` points at the `Task`
 *     tool_use and whose `data.message` carries a nested TranscriptEntry.
 *   - A separate JSONL file at
 *     `<transcript_dir>/<transcript_basename>/subagents/agent-<agentId>.jsonl`.
 */

/**
 * A single content block inside a message's `content` array.
 */
export interface ContentBlock {
  type: string;
  /** Present on `text` blocks. */
  text?: string;
  /** Present on `tool_use` blocks. */
  id?: string;
  name?: string;
  input?: Record<string, unknown>;
  /** Present on `tool_result` blocks. */
  tool_use_id?: string;
  content?: string | ContentBlock[];
  is_error?: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

/**
 * Token usage reported on assistant messages (Anthropic format).
 */
export interface Usage {
  input_tokens?: number;
  output_tokens?: number;
  cache_creation_input_tokens?: number;
  cache_read_input_tokens?: number;
}

/**
 * Anthropic-style message envelope used by Claude Code entries.
 */
export interface Message {
  role: string;
  content: string | ContentBlock[];
  model?: string;
  usage?: Usage;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

/**
 * Metadata block attached to a `user` entry that carries a tool result.
 * For `Task` tool results, `agentId` points at the sub-agent transcript file.
 */
export interface ToolUseResult {
  status?: string;
  agentId?: string;
  totalDurationMs?: number;
  success?: boolean;
  commandName?: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

/**
 * Payload of a `progress` entry describing incremental sub-agent activity.
 */
export interface ProgressData {
  type: string;
  agentId: string;
  prompt: string;
  message: TranscriptEntry;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

/**
 * A single entry in a Claude Code JSONL transcript.
 */
export interface TranscriptEntry {
  type: 'user' | 'assistant' | 'progress' | 'queue-operation' | string;
  message?: Message;
  timestamp?: string | number;
  sessionId?: string;
  agentId?: string;
  version?: string;
  permissionMode?: string;
  isCompactSummary?: boolean;
  toolUseResult?: ToolUseResult;
  cwd?: string;

  /** Present on `progress` entries. */
  parentToolUseID?: string;
  toolUseID?: string;
  data?: ProgressData;

  /** Present on `queue-operation` entries. */
  operation?: string;
  content?: string;

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

/**
 * Stop hook input received via stdin.
 */
export interface StopHookInput {
  session_id: string;
  transcript_path: string | null;
  cwd?: string;
  hook_event_name?: string;
}

/**
 * Anthropic-format message used in LLM span inputs.
 */
export interface AnthropicMessage {
  role: string;
  content: string | ContentBlock[];
}
