[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/claude-code/src/transcript.ts", "content": "/**
 * Transcript parsing utilities for Claude Code JSONL files.
 *
 * Claude Code writes one JSON object per line. Entries are emitted in
 * chronological order, so we walk them sequentially for span creation.
 */

import { readFileSync } from 'node:fs';
import type { ContentBlock, TranscriptEntry } from './types.js';

/** Nanoseconds per millisecond / second, and the numeric-timestamp thresholds. */
const NS_PER_MS = 1e6;
const NS_PER_SEC = 1e9;
const NANOSECOND_THRESHOLD = 1e13;
const MILLISECOND_THRESHOLD = 1e10;

/** Prefix used by skill-injection user messages, which are not real prompts. */
const SKILL_INJECTION_PREFIX = 'Base directory:';

/** Read a JSONL transcript file and parse each non-empty line into an entry. */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * - ISO date strings are parsed via `Date` and scaled from ms to ns.
 * - Numeric values are interpreted by magnitude: `>= 1e13` are already
 *   nanoseconds, `>= 1e10` are milliseconds, otherwise Unix seconds.
 *
 * Returns null for null/undefined/empty-string input and for strings that
 * are not valid ISO date strings.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts === null || ts === undefined || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (ts >= NANOSECOND_THRESHOLD) {
      return Math.floor(ts);
    }
    if (ts >= MILLISECOND_THRESHOLD) {
      return Math.floor(ts * NS_PER_MS);
    }
    return Math.floor(ts * NS_PER_SEC);
  }

  const ms = new Date(ts).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NS_PER_MS);
}

/**
 * Extract plain text from a message content value. If content is a string it
 * is returned unchanged. If content is an array of blocks, the `text` fields
 * of all `text` blocks are joined with newlines. An empty array yields `''`.
 */
export function extractTextContent(
  content: string | Array<{ type: string; text?: string; [key: string]: any }>,
): string {
  if (typeof content === 'string') {
    return content;
  }
  if (Array.isArray(content)) {
    return content
      .filter((block) => block.type === 'text')
      .map((block) => block.text ?? '')
      .join('\n');
  }
  return '';
}

/** True when a `user` entry's content is composed of tool_result blocks. */
function isToolResultEntry(entry: TranscriptEntry): boolean {
  const content = entry.message?.content;
  return (
    Array.isArray(content) &&
    content.length > 0 &&
    content.every((block) => (block as ContentBlock).type === 'tool_result')
  );
}

/**
 * Determine whether a user entry is a "real" user message — i.e. not a
 * tool-result carrier, not a compaction summary, and not a skill-injection
 * message (whose text starts with `Base directory:`).
 */
function isRealUserMessage(entry: TranscriptEntry): boolean {
  if (entry.type !== 'user') {
    return false;
  }
  if (entry.isCompactSummary === true) {
    return false;
  }
  if (isToolResultEntry(entry)) {
    return false;
  }
  const text = extractTextContent(entry.message?.content ?? '');
  if (text.startsWith(SKILL_INJECTION_PREFIX)) {
    return false;
  }
  return true;
}

/**
 * Find the index of the first "real" user message, or null if none exists.
 */
export function findFirstUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = 0; i < entries.length; i++) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Find the index of the last "real" user message. Skips tool-result carriers,
 * compaction summaries, and skill-injection messages. Returns null for an
 * empty transcript (or when no real user message exists).
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  if (entries.length === 0) {
    return null;
  }
  for (let i = entries.length - 1; i >= 0; i--) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Search from `startIndex` onward for the last assistant entry that carries
 * text content, returning that text (or null if none is found).
 */
export function findFinalAssistantResponse(
